  /* handle_options() assumes arg0 (program name) always exists */
  assert(argc && *argc >= 1);
  assert(argv && *argv);
  (*argc)--; /* Skip the program name */
  (*argv)++; /*      --- || ----      */
  init_variables(longopts, init_one_value);

