    }
    /* skip persist args separator */
    if (!is_persist_arg && my_getopt_is_ro_persist_args_separator(cur_arg)) {
      is_persist_arg = true;
      if (my_getopt_skip_unknown)
        (*argv)[argvpos++] = cur_arg;
      else
        (*argc)--;
