                  ? (*getopt_get_addr)(key_name, strlen(key_name), optp, &error)
                  : optp->value;
          if (error) return error;
        }
        if (optp->arg_type == NO_ARG) {
          /*
            Due to historical reasons GET_BOOL var_types still accepts arguments
