          if (!is_cmdline_arg || !*++pos) {
            if (my_getopt_print_errors)
              my_getopt_error_reporter(ERROR_LEVEL, EE_OPTION_REQUIRES_ARGUMENT,
                                       my_progname, optp->name);
            return EXIT_ARGUMENT_REQUIRED;
          }
          argument = *pos;
          (*argc)--;
        } else
          argument = optend;

