                  argument = *++pos;
                  (*argc)--;
                  /* the other loop will break, because *optend + 1 == 0 */
                }
              }
              int error;
              if ((error =
                       setval(optp, optp->value, argument, set_maximum_value)))
                return error;
              if (get_one_option && get_one_option(optp->id, optp, argument))
                return EXIT_UNSPECIFIED_ERROR;
              break;
